module sort4(input [3:0] a0,a1,a2,a3, output [3:0] s0,s1,s2,s3);
  wire [3:0] l0,l1,l2,l3; // stage1: (0,1),(2,3)
  assign {l0,l1} = (a0<=a1) ? {a0,a1} : {a1,a0};
  assign {l2,l3} = (a2<=a3) ? {a2,a3} : {a3,a2};
  wire [3:0] m0,m2,m1,m3; // stage2: (0,2),(1,3)
  assign {m0,m2} = (l0<=l2) ? {l0,l2} : {l2,l0};
  assign {m1,m3} = (l1<=l3) ? {l1,l3} : {l3,l1};
  assign s0 = m0; assign s3 = m3;
  assign {s1,s2} = (m1<=m2) ? {m1,m2} : {m2,m1};
endmodule

module sort4(input [3:0] a0,a1,a2,a3, output reg [3:0] s0,s1,s2,s3);
  // rank-based, stable: rank_i = #{j: a_j < a_i or (a_j==a_i and j<i)}
  wire l01 = a0 <= a1;   // a0 before a1
  wire l02 = a0 <= a2;
  wire l03 = a0 <= a3;
  wire l12 = a1 <= a2;
  wire l13 = a1 <= a3;
  wire l23 = a2 <= a3;
  wire [1:0] r0 = (!l01)+(!l02)+(!l03);
  wire [1:0] r1 = l01+(!l12)+(!l13);
  wire [1:0] r2 = l02+l12+(!l23);
  wire [1:0] r3 = l03+l13+l23;
  // note r_i counts elements before i
  always @* begin
    s0=0;s1=0;s2=0;s3=0;
    // output k = element with rank k
    s0 = (r0==0)?a0:(r1==0)?a1:(r2==0)?a2:a3;
    s1 = (r0==1)?a0:(r1==1)?a1:(r2==1)?a2:a3;
    s2 = (r0==2)?a0:(r1==2)?a1:(r2==2)?a2:a3;
    s3 = (r0==3)?a0:(r1==3)?a1:(r2==3)?a2:a3;
  end
endmodule

module sort4(input [3:0] a0,a1,a2,a3, output [3:0] s0,s1,s2,s3);
  wire [3:0] l0,l1,l2,l3;
  assign {l0,l1} = (a0<=a1) ? {a0,a1} : {a1,a0};
  assign {l2,l3} = (a2<=a3) ? {a2,a3} : {a3,a2};
  wire c02 = l0<=l2, c13 = l1<=l3, c12 = l1<=l2, c03 = l0<=l3;
  assign s0 = c02 ? l0 : l2;
  assign s3 = c13 ? l3 : l1;
  assign s1 = c02 ? (c12 ? l1 : l2) : (c03 ? l0 : l3);
  assign s2 = c13 ? (c12 ? l2 : l1) : (c03 ? l3 : l0);
endmodule

module sort4(input [3:0] a0,a1,a2,a3, output [3:0] s0,s1,s2,s3);
  function [7:0] ce(input [3:0] x, input [3:0] y);
    reg [4:0] d;
    begin d = {1'b0,y} - {1'b0,x}; // borrow set when y<x
